import json
from pathlib import Path
p=Path('PCB');a=json.loads((p/'manifests/power-layout-v07.json').read_text());cs=json.loads((p/'manifests/pcb-pads-before-v07.json').read_text(encoding='utf-8-sig'))['result'];nets=sorted({q['net'] for c in cs if c['ref'] in a['positions'] for q in c['pads'] if q['net']});specs=[{'ref':r,'x':v['xMm']/.0254,'y':v['yMm']/.0254,'rotation':v['rotation']} for r,v in a['positions'].items()];guard='if((await eda.dmt_SelectControl.getCurrentDocumentInfo())?.uuid!=="4211128ecf040c100b33238447713203")throw Error("Wrong PCB");'
code=guard+'const nets='+json.dumps(nets)+';for(const q of await eda.pcb_PrimitiveLine.getAll())if(nets.includes(q.getState_Net()))await eda.pcb_PrimitiveLine.delete(q);for(const q of await eda.pcb_PrimitiveVia.getAll())if(nets.includes(q.getState_Net()))await eda.pcb_PrimitiveVia.delete(q);for(const q of await eda.pcb_PrimitivePolyline.getAll())if(nets.includes(q.getState_Net()))await eda.pcb_PrimitivePolyline.delete(q);const specs='+json.dumps(specs)+';const cs=await eda.pcb_PrimitiveComponent.getAll();for(const z of specs){const c=cs.find(c=>c.getState_Designator()===z.ref);if(!c)throw Error("Missing "+z.ref);await eda.pcb_PrimitiveComponent.modify(c,{x:z.x,y:z.y,rotation:z.rotation});}return {moved:specs.length,removedNets:nets,saved:await eda.pcb_Document.save()};';(p/'scripts/place-power-v07.js').write_text(code)
